import{z as i,x as d,o as B,c as o,q as n,j as l,D as t,d as e,s as A,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"CEX-DEX 套利","description":"","frontmatter":{"title":"CEX-DEX 套利","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cex-dex-arb.md","filePath":"quant/cex-dex-arb.md","lastUpdated":1791063341000}'),p={name:"quant/cex-dex-arb.md"};function D(C,E,m,h,X,c){const r=d("Mermaid");return B(),o("div",null,[E[2]||(E[2]=n('<h1 id="cex-dex-套利" tabindex="-1">CEX-DEX 套利 <a class="header-anchor" href="#cex-dex-套利" aria-label="Permalink to &quot;CEX-DEX 套利&quot;">​</a></h1><div class="epigraph"><p>同一资产在限价簿中点与 AMM 储备比上可以暂时不一致；当偏离超过费用、冲击、提现与库存成本，公开的经济压力是把两边的价格重新钉进一条带里，而不是某处存在免费的确定性利润。</p><footer>—— 一价定律与空间套利的市场微观结构；DEX 侧价格见 Adams 等 Uniswap 白皮书；排序租金背景见 Daian et al., Flash Boys 2.0</footer></div><p><a href="/quant/mev-sandwich">上一课</a>把三明治租金写成透明内存池中已声明滑点缓冲与区块排序权的结合，会计上应与 AMM 曲线的固有冲击分开。缺口是另一条公共信息差：CEX 用连续限价簿，DEX 用恒定乘积或集中流动性，同一代币相对同一报价资产的中点经常不一致。一价定律只以带状成立——费用、冲击、准入与结算时钟不同。本课写这条带如何被撑开、价格压力如何指向收敛，以及为何把带内噪声当成可锁定价差会把库存做成伪 alpha。不重写三明治的插入。对象不是跨所执行路径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记 CEX 中间价为 \\(S_{\\mathrm{c}}\\)（买卖价中点），DEX 现货为 \\(p=y/x\\)（或 v3 当前 tick 的边际价）。粗偏离</p> \\[\\delta=\\ln(p/S_{\\mathrm{c}}) \\]<p>在零费用、无限深度、瞬时双向结算的世界里应被立刻打到零。真实世界里 \\(\\delta\\) 可以在一个正宽度里随机游走：DEX 成交稀疏时 \\(p\\) 停滞，CEX 先反映信息；或反过来，链上大单先推动 \\(p\\)，CEX 尚未跟上。问题是把 \\(\\delta\\) 分解成：<strong>不可套利的成本带</strong>、<strong>带外的经济压力</strong>、以及<strong>不能用中点计算的冲击与结算风险</strong>。忽略后两项，任何历史 \\(|\\delta|\\) 的均值都会看起来像「年化收益」。</p><p>成本带不是常数。它至少包含：DEX 费率与 CEX 的 taker/maker 费，见 <a href="/quant/maker-taker">maker-taker</a>；AMM 曲线冲击与 CEX 簿的档位冲击；链上资源费；充提、托管或跨系统库存无法瞬时对冲时的价格风险；稳定币或计价资产本身的折溢价，见 <a href="/quant/stablecoin-depeg">脱锚</a>。带的宽度随波动、深度与拥堵变化。公开研究与做市会计要估的是带，不是某一刻 \\(\\delta\\) 的符号。</p><p><span class="marginnote">数字实例：DEX 费率 0.3%，CEX taker 费 0.1%，链上 gas 与充提折合 0.05%，冲击成本留 0.1%——光显性成本就撑出约 0.5% 的带。此时看到 \\(\\delta=0.2\\%\\)，不是机会而是噪声；只有 \\(\\delta\\) 明显超出这类合计成本，才谈得上带外压力。初学者最容易在这里把「价差存在」误读成「价差可赚」。</span></p><h3 id="中点差不等于可成交价差" tabindex="-1">中点差不等于可成交价差 <a class="header-anchor" href="#中点差不等于可成交价差" aria-label="Permalink to &quot;中点差不等于可成交价差&quot;">​</a></h3><p>\\(S_{\\mathrm{c}}\\) 是买卖中点，\\(p\\) 是曲线切线。可成交的是 CEX 的可立即成交价（卖一/买一或更深的加权）与 DEX 沿曲线的<strong>均价</strong>。大额时两边冲击可以吞掉全部 \\(\\delta\\)。Uniswap v2/v3 白皮书给出的正是均价如何随数量恶化；限价簿则按档位累加。用两个中点的历史差做回测，等价于假设自己永远是无穷小且永远吃到中点——这在任何市场上都不是可交易的 P&amp;L。正确的经济比较是两条<strong>供给曲线</strong>之间的面积，扣掉费用与失败/延迟的期权价值。</p><p><span class="marginnote">「CEX-DEX 套利」在媒体里常被说成无风险。空间套利的经典结论是：风险在搬运与库存上。一边成交、另一边尚未成交，残留的是方向性敞口；链上腿还对区块排序敏感。把这种敞口写成零，只是把风险藏进了假设。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>度量。同步时钟下记录 \\(S_{\\mathrm{c}}(t)\\) 与 \\(p(t)\\)，但要承认 \\(t\\) 在 CEX 是撮合引擎时钟，在 DEX 是区块时钟，二者不可逐毫秒对齐。公开做法是：以区块为 DEX 的观察点，取该时刻前后一个极短窗的 CEX 报价做区间，而不是假装存在共同的连续时间。然后在若干标准规模上计算两边的可成交均价，得到规模依赖的 \\(\\delta(q)\\)。只有 \\(\\delta(q)\\) 仍超出费用与预估延迟成本时，经济压力才被定义为「带外」。带外并不等于利润已实现，它只说明：若有人已经同时拥有两边的库存与通道，其最优是把库存从贵的一侧挪到便宜的一侧，直到 \\(\\delta(q)\\) 回到带内。</p><p>收敛机制。DEX 侧，外部价格持续偏离会吸引与 <a href="/quant/uniswap-cpmm">CPMM</a> 节所述同一方向的库存交易，把 \\(p\\) 推向 \\(S_{\\mathrm{c}}\\)；CEX 侧，同样的库存交易改变簿的中点。两边都动，分担发现。若 DEX 深度相对 CEX 极薄，几乎全部调整发生在 \\(p\\)；若某代币的价格发现主要在链上，则 \\(S_{\\mathrm{c}}\\) 会跟。Hasbrouck 信息份额的逻辑在此适用：哪一侧先动、哪一侧跟，是经验问题，随币对与时段而变，不能先验写成「CEX 永远领先」。</p><h3 id="资金费率、充提闸门与计价资产" tabindex="-1">资金费率、充提闸门与计价资产 <a class="header-anchor" href="#资金费率、充提闸门与计价资产" aria-label="Permalink to &quot;资金费率、充提闸门与计价资产&quot;">​</a></h3><p>永续合约与现货 CEX、链上现货之间还有第三种价格，见 <a href="/quant/crypto-perp-funding">资金费</a> 与 <a href="/quant/crypto-basis-trade">期现基差</a>。把永续中点与 AMM 现货直接相减，混进了资金与杠杆溢价，不是纯现货空间差。充提暂停、链拥堵、稳定币临时折价，会把「理论上可搬运」变成不可搬运，带的宽度瞬时爆炸，\\(\\delta\\) 可以长时间停在带外而不构成可锁定价差——因为锁价所需的第二条腿不存在。会计上这是基差风险，与外汇无法交割时的 NDF 类似。公开规则（暂停充提、保证金参数、池的费率档）是状态变量，应进入带的估计，而不是当作异常值删掉。</p>',17)),(B(),l(s,null,{default:t(()=>[A(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Cex%5B%22CEX%20%E9%99%90%E4%BB%B7%E7%B0%BF%E4%B8%AD%E7%82%B9%22%5D%20--%3E%20Mid%5B%22%E4%B8%AD%E7%82%B9%E5%B7%AE%20%CE%B4%22%5D%0A%20%20Dex%5B%22DEX%20%E5%82%A8%E5%A4%87%E6%AF%94%20%2F%20tick%20%E4%BB%B7%22%5D%20--%3E%20Mid%0A%20%20Mid%20--%3E%20Band%5B%22%E8%B4%B9%E7%94%A8%20%2B%20%E5%86%B2%E5%87%BB%20%2B%20%E5%BB%B6%E8%BF%9F%E6%88%90%E6%9C%AC%E5%B8%A6%22%5D%0A%20%20Band%20--%3E%20In%5B%22%E5%B8%A6%E5%86%85%3A%20%E5%99%AA%E5%A3%B0%E4%B8%8E%E4%B8%8D%E5%8F%AF%E5%A5%97%E5%88%A9%22%5D%0A%20%20Band%20--%3E%20Out%5B%22%E5%B8%A6%E5%A4%96%3A%20%E5%BA%93%E5%AD%98%E5%8E%8B%E5%8A%9B%E6%8C%87%E5%90%91%E6%94%B6%E6%95%9B%22%5D%0A%20%20Out%20--%3E%20Inv%5B%22%E4%B8%A4%E8%BE%B9%E5%BA%93%E5%AD%98%E4%B8%8E%E7%BB%93%E7%AE%97%E6%97%B6%E9%92%9F%22%5D%0A%20%20Inv%20--%3E%20Risk%5B%22%E6%9C%AA%E5%AF%B9%E5%86%B2%E6%AE%8B%E5%B7%AE%E4%B8%8E%E5%9F%BA%E5%B7%AE%22%5D%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"经济压力的方向总是：在定价偏贵的场所减少多头库存（或增加空头），在定价偏便宜的场所增加多头。CPMM 上这意味着沿曲线与外部中点相反的方向交易；限价簿上这意味着吃掉过时的档或挂到新的中点。压力使 \\(\\delta\\) 均值回复，回复速度由两边深度、到达率与链上包含延迟决定。波动升高时，信息到达快于搬运，带外时间变长，这不是「alpha 更好」，而是风险更高：残差敞口的方差同时上升。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：同一箱苹果在这座城市卖 20 元、邻城卖 25 元。真正能锁定的不是 5 元价差，而是 5 元减去运费、路上碰坏的损耗，以及到货前价格可能跌回 20 元的风险。CEX-DEX 套利里，「运费」是费率与 gas，「损耗」是冲击成本，「价格跌回去」就是你只成交了一条腿时的敞口。")],-1)),E[6]||(E[6]=a("p",null,[e("Daian 等人指出，DEX 腿若来自公开内存池，则这组库存交易自身对排序敏感，其利润可能被优先费竞争耗散，成为 MEV 的一部分。CEX 腿若在传统撮合里，则面对的是 "),a("a",{href:"/quant/latency-arbitrage"},"延迟套利"),e(" 与队列。跨系统套利因此有两套微观结构税。社会层面，带外压力有价格发现功能：它把孤立池的过时储备比拉向更有信息的报价。私人层面，税后期望可以接近零，尤其当竞争者同样观察到公开的 \\(\\delta\\)。把历史带外幅度的一半当成策略收益，忽略的正是这一耗散。")],-1)),(B(),l(s,null,{default:t(()=>[A(r,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20GAP%5B%22%E5%B8%A6%E5%A4%96%E5%81%8F%E7%A6%BB%20%CE%B4%22%5D%20--%3E%20WHO%7B%22%E5%93%AA%E4%B8%80%E4%BE%A7%E6%B7%B1%E5%BA%A6%E6%9B%B4%E8%96%84%EF%BC%9F%22%7D%0A%20%20WHO%20--%3E%7C%22DEX%20%E8%96%84%22%7C%20P1%5B%22%E8%B0%83%E6%95%B4%E5%87%A0%E4%B9%8E%E5%85%A8%E5%9C%A8%20p%EF%BC%9A%E5%BA%93%E5%AD%98%E4%BA%A4%E6%98%93%E6%8E%A8%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20WHO%20--%3E%7C%22CEX%20%E8%96%84%22%7C%20P2%5B%22%E8%B0%83%E6%95%B4%E5%8F%91%E7%94%9F%E5%9C%A8%20S_c%EF%BC%9A%E5%90%83%E6%A1%A3%20%2F%20%E6%8C%82%E6%96%B0%E4%B8%AD%E7%82%B9%22%5D%0A%20%20WHO%20--%3E%7C%22%E4%B8%A4%E8%BE%B9%E7%9B%B8%E5%BD%93%22%7C%20P3%5B%22%E5%88%86%E6%8B%85%E4%BB%B7%E6%A0%BC%E5%8F%91%E7%8E%B0%22%5D%0A%20%20P1%20--%3E%20MEV%5B%22%E9%93%BE%E4%B8%8A%E8%85%BF%E8%BF%9B%E5%85%AC%E5%BC%80%E5%86%85%E5%AD%98%E6%B1%A0%EF%BC%8C%E5%88%A9%E6%B6%A6%E8%A2%AB%E4%BC%98%E5%85%88%E8%B4%B9%E7%AB%9E%E4%BA%89%E8%80%97%E6%95%A3%22%5D%0A%20%20P2%20--%3E%20QUEUE%5B%22CEX%20%E8%85%BF%E9%9D%A2%E5%AF%B9%E9%98%9F%E5%88%97%E4%B8%8E%E5%BB%B6%E8%BF%9F%E7%AB%9E%E4%BA%89%22%5D%0A%20%20P3%20--%3E%20BOTH%5B%22%E4%B8%A4%E5%A5%97%E5%BE%AE%E8%A7%82%E7%BB%93%E6%9E%84%E7%A8%8E%E5%8F%A0%E5%8A%A0%22%5D%0A%20%20MEV%20--%3E%20NET%5B%22%E7%A8%8E%E5%90%8E%E6%9C%9F%E6%9C%9B%E8%B6%8B%E8%BF%91%E9%9B%B6%22%5D%0A%20%20QUEUE%20--%3E%20NET%0A%20%20BOTH%20--%3E%20NET%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=n('<h3 id="为何「看起来能套利」经常不可交割" tabindex="-1">为何「看起来能套利」经常不可交割 <a class="header-anchor" href="#为何「看起来能套利」经常不可交割" aria-label="Permalink to &quot;为何「看起来能套利」经常不可交割&quot;">​</a></h3><p>教科书套利要求同时、反向、可交割。CEX 与 DEX 的同时性被区块时间破坏；反向被借贷、做空规则与保证金破坏；交割被充提配额与合规账户破坏。剩余的是统计上的均值回复交易：有库存、有失败率、有尾部。失败率在拥堵与波动共发时上升，而这正是 \\(|\\delta|\\) 最大的时候——样本内最大的「价差」与最差的执行条件绑定。这与期货 <a href="/quant/cash-and-carry">期现</a> 在交割通道关闭时基差可以乱涨是同一类制度约束。公开分析应报告条件期望：在充提正常、两边都可成交的子样本里，带外压力如何衰减；而不是无条件地平均所有 \\(|\\delta|\\)。</p><p><span class="marginnote">常见误区：把历史 \\(|\\delta|\\) 的均值除以 252 当成「日收益」。这个数混着三样东西：你根本吃不到的中点、必须双边成交才能锁住的价差、以及失败腿带来的方向性盈亏。正确的问题是条件期望——在两边都可成交且充提正常的样本里，扣除全部成本后还剩多少。</span></p><p><span class="marginnote">一价定律约束的是可转移的、同质的索取权。被包裹的代币、不同链上的「同名」资产、以及脱锚中的稳定币计价，都可能只是名字相同。\\(\\delta\\) 必须以可互换的结算资产来定义，否则比较的是两种东西。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本篇不把任何历史价差写成可实施策略，也不讨论如何连接两个系统。有意义的研究输出是：规模依赖的成本带、信息份额、带外持续时间的分布、以及制度状态（拥堵、暂停、脱锚）对带的调制。Uniswap 白皮书提供 DEX 价格与冲击的公式；限价簿微观结构提供 CEX 侧冲击；<em>Flash Boys 2.0</em> 提供链上腿与排序权的背景。三者合起来仍只是价格经济学。</p><p>稳定币作为计价单位时，\\(\\delta\\) 会吸收脱锚，见下一篇。集中流动性使 DEX 冲击呈阶梯状，小规模带可能很窄、大规模带突然变宽，用单一基点价差概括 v3 池会误导。跨多个 DEX 的三角关系（同一资产的若干池）是另一张图上的一价定律，机制相同，时钟仍是区块时间。不要用 CEX 的永续深度去推断 DEX 现货的可套利规模，也不要用 DEX 的瞬时 \\(p\\) 去标记 CEX 的全部风险。</p><p><span class="marginnote">回测若在 CEX 用最后成交、在 DEX 用区块末状态，二者都不是可下单价格。应使用当时的可成交曲线（簿与 AMM 状态）并计入随后一个间隔的价格移动作为延迟成本。这是执行会计，不是寻找漏洞。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CEX 中点与 DEX 储备比的差，首先应被解释为带有宽度的一价定律，宽度由费用、冲击、时钟与搬运约束决定。</li><li>经济压力在带外指向收敛，但收敛靠库存移动，残留敞口与结算失败使它不是锁定价差。</li><li>中点差高估可成交空间；规模依赖的均价差才是比较对象。</li><li>链上腿对排序敏感，部分表面价差会在优先费中耗散，见 Daian 等人对 DEX 套利作为 MEV 的讨论。</li><li>出处：Adams 等 Uniswap v2/v3 白皮书中的价格与冲击；Daian et al., <em>Flash Boys 2.0</em>, 2020；空间套利与信息份额属标准市场微观结构。</li></ul>',10))])}const f=i(p,[["render",D]]);export{F as __pageData,f as default};
